  &reftitle.examples;

   Exemplo de Yaf_View_Simple::render


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function detailAction()
    {
        /* renderiza o modelo e pós-processa o resultado */
        $html = $this->getView()->render("product/detail.phtml", array(
            "name"  => "Yaf in Action",
            "price" => "29.90",
        ));

        $this->getResponse()->setBody($html);
        return false; // ignora a renderização automática
    }
}
?>




   Exemplo de modelo


<h1><?php echo $name; ?></h1>
<p>Price: <?php echo $price; ?> EUR</p>


